  // Simple Markdown to HTML formatter for survey sections
  function formatMarkdown(text) {
    if (!text) return '';
    var raw = escapeHtml(text);

    // Markdown Table parsing
    var lines = raw.split(/\r?\n/);
    var inTable = false;
    var tableHtml = '';
    var outLines = [];

    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].trim();
      if (line.indexOf('|') === 0 && line.lastIndexOf('|') === line.length - 1) {
        // Table row
        var cells = line.split('|').slice(1, -1);
        if (cells.length > 0 && cells[0].indexOf('---') !== -1) {
          // separator row, skip
          continue;
        }
        if (!inTable) {
          inTable = true;
          tableHtml = '<div class="guide-table-responsive"><table class="guide-table"><tbody>';
        }
        tableHtml += '<tr>';
        for (var c = 0; c < cells.length; c++) {
          var cellContent = cells[c].trim();
          tableHtml += '<td>' + cellContent + '</td>';
        }
        tableHtml += '</tr>';
      } else {
        if (inTable) {
          inTable = false;
          tableHtml += '</tbody></table></div>';
          outLines.push(tableHtml);
          tableHtml = '';
        }
        outLines.push(line);
      }
    }
    if (inTable) {
      tableHtml += '</tbody></table></div>';
      outLines.push(tableHtml);
    }

    var result = outLines.join('\n');

    // Bold **text**
    result = result.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
    // Italic *text*
    result = result.replace(/\*(.+?)\*/g, '<em>$1</em>');
    // Headers ###
    result = result.replace(/^###\s+(.+)$/gm, '<h4 class="guide-md-h4">$1</h4>');
    result = result.replace(/^##\s+(.+)$/gm, '<h3 class="guide-md-h3">$1</h3>');
    // Unordered lists * or -
    result = result.replace(/^[\*\-]\s+(.+)$/gm, '<li class="guide-md-li">$1</li>');
    // Numbered lists 1.
    result = result.replace(/^\d+\.\s+(.+)$/gm, '<li class="guide-md-li-num">$1</li>');

    // Paragraph breaks (double newlines)
    var paras = result.split(/\n\s*\n/);
    var formatted = paras.map(function(p) {
      p = p.trim();
      if (!p) return '';
      if (p.indexOf('<div class="guide-table-responsive">') === 0 ||
          p.indexOf('<h3') === 0 || p.indexOf('<h4') === 0) {
        return p;
      }
      if (p.indexOf('<li') !== -1) {
        return '<ul class="guide-md-ul">' + p + '</ul>';
      }
      return '<p class="guide-md-p">' + p.replace(/\n/g, '<br>') + '</p>';
    }).join('');

    return formatted;
  }

